9	const BASE_PREMIUMS = {
10	  sword: 100,
11	  amulet: 60,
12	  staff: 80,
13	  potion: 40,
14	  rune: 25,
15	} as const satisfies Record<string, number>;
16	
17	type InsurableItemType = keyof typeof BASE_PREMIUMS;
18	
19	type Item = {
20	  type: InsurableItemType;
21	};
22	
23	type QuoteStep = {
24	  op: "quote";
25	  items: Item[];
26	};
27	
28	type Customer = {
29	  yearsWithMHPCO: number;
30	};
31	
32	type Scenario = {
33	  customer: Customer;
34	  steps: QuoteStep[];
35	};
36	
37	const PROCESSING_FEE = 5;
38	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
39	
40	const percentOf = (amount: number, percent: number): number =>
41	  (amount * percent) / 100;
42	
43	// The MHPCO always rounds in its own favour: premiums (which the customer
44	// pays) go up. Payouts round down, but no test demands that yet.
45	const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
46	
47	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
48	
49	const BLOCK_SIZE = 3;
50	const BLOCK_BASE_PREMIUM = 60;
51	
52	const policyBasePremiumOf = (items: Item[]): number => {
53	  if (items.length === BLOCK_SIZE && items.every((item) => item.type === "rune")) {
54	    return BLOCK_BASE_PREMIUM;
55	  }
56	
57	  return items.reduce((sum, item) => sum + basePremiumOf(item), 0);
58	};
59	
60	const quote = (step: QuoteStep): QuoteResult => {
61	  const basePremium = policyBasePremiumOf(step.items);
62	  const initialAssessmentSurcharge = percentOf(
63	    basePremium,
64	    INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
65	  );
66	
67	  return {
68	    premium: roundedUpInMHPCOsFavour(
69	      basePremium + initialAssessmentSurcharge + PROCESSING_FEE,
70	    ),
71	  };
72	};
73	
74	export const runScenario = (scenario: Scenario): ScenarioResult => {
75	  return { results: scenario.steps.map(quote) };
76	};
