const itemBasePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

// Three components of the same type form a "building block" priced as a unit
// rather than per item.
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const isBlockOfThreeAlike = (items: Item[]): boolean =>
  items.length === BLOCK_SIZE &&
  items.every((item) => item.type === items[0].type);

// Only whole-policy blocks are recognised so far; a policy that merely
// contains a block is the next test's job.
const policyBasePremiumOf = (items: Item[]): number => {
  if (isBlockOfThreeAlike(items)) {
    return BLOCK_BASE_PREMIUM;
  }

  return items.reduce((sum, item) => sum + itemBasePremiumOf(item), 0);
};
